export const physicsCards=[
{id:'phys-speed',group:'motion',title:T('Speed','Geschwindigkeit','Rapidez','Vitesse'),note:T('Speed is the distance travelled divided by the time taken.','Die Geschwindigkeit ist die zurückgelegte Strecke geteilt durch die benötigte Zeit.','La rapidez es la distancia recorrida dividida entre el tiempo empleado.','La vitesse est la distance parcourue divisée par la durée.'),formula:'v = Δs / Δt',substitution:'{s} / {t}',fields:[F('s','distance','Δs','m',20,'nonnegative'),F('t','duration','Δt','s',4,'positive')],result:'v',unit:'m/s'},
{id:'phys-acceleration',group:'motion',title:T('Acceleration','Beschleunigung','Aceleración','Accélération'),note:T('Acceleration is the change of speed divided by the time interval.','Die Beschleunigung ist die Geschwindigkeitsänderung geteilt durch das Zeitintervall.','La aceleración es el cambio de rapidez dividido entre el intervalo de tiempo.','L’accélération est la variation de vitesse divisée par l’intervalle de temps.'),formula:'a = Δv / Δt',substitution:'{dv} / {t}',fields:[F('dv','speedChange','Δv','m/s',10,'signed'),F('t','duration','Δt','s',2,'positive')],result:'a',unit:'m/s²'},
{id:'phys-uniform',group:'motion',title:T('Distance at constant speed','Strecke bei konstanter Geschwindigkeit','Distancia a rapidez constante','Distance à vitesse constante'),note:T('At constant speed, distance is speed times time.','Bei konstanter Geschwindigkeit ist die Strecke Geschwindigkeit mal Zeit.','A rapidez constante, la distancia es rapidez por tiempo.','À vitesse constante, la distance est vitesse fois durée.'),formula:'s = v t',substitution:'{v} × {t}',fields:[F('v','speed','v','m/s',5,'nonnegative'),F('t','duration','t','s',4,'nonnegative')],result:'s',unit:'m'},
{id:'phys-accel-speed',group:'motion',title:T('Speed at constant acceleration','Geschwindigkeit bei konstanter Beschleunigung','Rapidez con aceleración constante','Vitesse à accélération constante'),note:T('With constant acceleration, the speed is the initial speed plus acceleration times time.','Bei konstanter Beschleunigung ist die Geschwindigkeit die Anfangsgeschwindigkeit plus Beschleunigung mal Zeit.','Con aceleración constante, la rapidez es la rapidez inicial más aceleración por tiempo.','À accélération constante, la vitesse est la vitesse initiale plus accélération fois durée.'),formula:'v = v₀ + a t',substitution:'{v0} + {a} × {t}',fields:[F('v0','initialSpeed','v₀','m/s',0,'signed'),F('a','acceleration','a','m/s²',2,'signed'),F('t','duration','t','s',3,'nonnegative')],result:'v',unit:'m/s'},
{id:'phys-accel-distance',group:'motion',title:T('Distance at constant acceleration','Strecke bei konstanter Beschleunigung','Distancia con aceleración constante','Distance à accélération constante'),note:T('From rest is not required: s = v₀t + ½at². Free fall uses the free-fall acceleration for a.','Start aus der Ruhe ist nicht nötig: s = v₀t + ½at². Beim freien Fall ist a die Fallbeschleunigung.','No hace falta partir del reposo: s = v₀t + ½at². En caída libre, a es la aceleración de caída.','Le départ au repos n’est pas exigé : s = v₀t + ½at². En chute libre, a est l’accélération de chute.'),formula:'s = v₀t + ½ a t²',substitution:'{v0} × {t} + 0.5 × {a} × {t}²',fields:[F('v0','initialSpeed','v₀','m/s',0,'signed'),F('a','acceleration','a','m/s²',2,'signed'),F('t','duration','t','s',3,'nonnegative')],result:'s',unit:'m'},
{id:'phys-accel-link',group:'motion',title:T('Speed, acceleration and distance','Geschwindigkeit, Beschleunigung und Strecke','Rapidez, aceleración y distancia','Vitesse, accélération et distance'),note:T('Without using the time explicitly, v² = v₀² + 2as. A negative result under the square root is impossible for a real speed.','Ohne die Zeit explizit zu verwenden gilt v² = v₀² + 2as. Ein negativer Wert unter der Wurzel ergibt keine reelle Geschwindigkeit.','Sin usar el tiempo de forma explícita, v² = v₀² + 2as. Un valor negativo bajo la raíz no da una rapidez real.','Sans utiliser explicitement la durée, v² = v₀² + 2as. Une valeur négative sous la racine ne donne pas une vitesse réelle.'),formula:'v = √(v₀² + 2 a s)',substitution:'√({v0}² + 2 × {a} × {s})',fields:[F('v0','initialSpeed','v₀','m/s',0,'signed'),F('a','acceleration','a','m/s²',5,'signed'),F('s','distance','s','m',10,'signed')],result:'v',unit:'m/s'},
{id:'phys-throw-horizontal',group:'motion',title:T('Horizontal throw, horizontal position','Waagerechter Wurf, waagerechte Position','Tiro horizontal, posición horizontal','Lancer horizontal, position horizontale'),note:T('Split the motion into components. Horizontally the speed stays constant, so x = v t.','Zerlege die Bewegung in Komponenten. Waagerecht bleibt die Geschwindigkeit konstant, also x = v t.','Separa el movimiento en componentes. En horizontal la rapidez se mantiene, así que x = v t.','Décompose le mouvement en composantes. Horizontalement la vitesse reste constante, donc x = v t.'),formula:'x = v t',substitution:'{v} × {t}',fields:[F('v','speed','v','m/s',8,'nonnegative'),F('t','duration','t','s',2,'nonnegative')],result:'x',unit:'m'},
{id:'phys-throw-vertical',group:'motion',title:T('Horizontal throw, vertical drop','Waagerechter Wurf, senkrechter Fall','Tiro horizontal, caída vertical','Lancer horizontal, chute verticale'),note:T('Vertically the body starts from rest and falls with the free-fall acceleration: y = ½gt².','Senkrecht startet der Körper aus der Ruhe und fällt mit der Fallbeschleunigung: y = ½gt².','En vertical el cuerpo parte del reposo y cae con la aceleración de caída: y = ½gt².','Verticalement le corps part du repos et tombe avec l’accélération de chute : y = ½gt².'),formula:'y = ½ g t²',substitution:'0.5 × {g} × {t}²',fields:[F('g','gravity','g','m/s²',9.81,'positive'),F('t','duration','t','s',1,'nonnegative')],result:'y',unit:'m'},
{id:'phys-newton',group:'forces',title:T('Force, mass and acceleration','Kraft, Masse und Beschleunigung','Fuerza, masa y aceleración','Force, masse et accélération'),note:T('In one dimension the force is the product of mass and acceleration.','In einer Dimension ist die Kraft das Produkt aus Masse und Beschleunigung.','En una dimensión la fuerza es el producto de la masa y la aceleración.','En une dimension, la force est le produit de la masse et de l’accélération.'),formula:'F = m a',substitution:'{m} × {a}',fields:[F('m','mass','m','kg',2,'positive'),F('a','acceleration','a','m/s²',3,'signed')],result:'F',unit:'N'},
{id:'phys-impulse',group:'forces',title:T('Force from a change of velocity','Kraft aus einer Geschwindigkeitsänderung','Fuerza a partir de un cambio de velocidad','Force à partir d’une variation de vitesse'),note:T('The written relation is F·Δt = m·Δv, so the force is m·Δv/Δt.','Die angegebene Beziehung lautet F·Δt = m·Δv, also ist die Kraft m·Δv/Δt.','La relación indicada es F·Δt = m·Δv, así que la fuerza es m·Δv/Δt.','La relation indiquée est F·Δt = m·Δv, donc la force vaut m·Δv/Δt.'),formula:'F = m Δv / Δt',substitution:'{m} × {dv} / {t}',fields:[F('m','mass','m','kg',2,'positive'),F('dv','speedChange','Δv','m/s',4,'signed'),F('t','duration','Δt','s',0.5,'positive')],result:'F',unit:'N'},
{id:'phys-weight',group:'forces',title:T('Weight','Gewichtskraft','Peso','Poids'),note:T('Weight is mass times the free-fall acceleration. Mass and weight are different quantities.','Die Gewichtskraft ist Masse mal Fallbeschleunigung. Masse und Gewichtskraft sind verschiedene Größen.','El peso es masa por la aceleración de caída libre. Masa y peso son magnitudes distintas.','Le poids est la masse fois l’accélération de chute. Masse et poids sont des grandeurs différentes.'),formula:'F = m g',substitution:'{m} × {g}',fields:[F('m','mass','m','kg',2,'positive'),F('g','gravity','g','m/s²',9.81,'positive')],result:'F',unit:'N'},
{id:'phys-centripetal',group:'forces',title:T('Centripetal force','Zentripetalkraft','Fuerza centrípeta','Force centripète'),note:T('For motion in a circle at constant speed, the inward force is m v²/r. Name the real force that plays this role.','Bei einer Kreisbewegung mit konstantem Tempo ist die nach innen gerichtete Kraft m v²/r. Benenne die reale Kraft, die diese Rolle übernimmt.','Para un movimiento circular a rapidez constante, la fuerza hacia dentro es m v²/r. Nombra la fuerza real que desempeña ese papel.','Pour un mouvement circulaire à vitesse constante, la force vers le centre est m v²/r. Nomme la force réelle qui joue ce rôle.'),formula:'F = m v² / r',substitution:'{m} × {v}² / {r}',fields:[F('m','mass','m','kg',2,'positive'),F('v','speed','v','m/s',3,'nonnegative'),F('r','radius','r','m',1,'positive')],result:'F',unit:'N'},
{id:'phys-gravity',group:'forces',title:T('Gravitational force','Gravitationskraft','Fuerza gravitatoria','Force de gravitation'),note:T('The gravitational force between two masses is G m₁ m₂ / r². G is the gravitational constant.','Die Gravitationskraft zwischen zwei Massen ist G m₁ m₂ / r². G ist die Gravitationskonstante.','La fuerza gravitatoria entre dos masas es G m₁ m₂ / r². G es la constante de gravitación.','La force de gravitation entre deux masses est G m₁ m₂ / r². G est la constante de gravitation.'),formula:'F = G m₁ m₂ / r²',substitution:'G × {m1} × {m2} / {r}²',fields:[F('m1','mass1','m₁','kg',2,'positive'),F('m2','mass2','m₂','kg',3,'positive'),F('r','separation','r','m',2,'positive')],result:'F',unit:'N',constants:T('G = 6.67430 × 10⁻¹¹ N·m²/kg².','G = 6,67430 × 10⁻¹¹ N·m²/kg².','G = 6,67430 × 10⁻¹¹ N·m²/kg².','G = 6,67430 × 10⁻¹¹ N·m²/kg².')},
{id:'phys-kepler-period',group:'forces',title:T('Kepler period from the semi-major axis','Kepler-Periode aus der großen Halbachse','Periodo de Kepler a partir del semieje mayor','Période de Kepler à partir du demi-grand axe'),note:T('For two orbits about the same central mass, T² is proportional to a³. The missing period is the known period times (a₂/a₁) to the power 3/2. Use one unit for both periods and one unit for both axes.','Für zwei Bahnen um dieselbe Zentralmasse ist T² proportional zu a³. Die fehlende Periode ist die bekannte Periode mal (a₂/a₁) hoch 3/2. Eine Einheit für beide Perioden und eine für beide Achsen verwenden.','Para dos órbitas alrededor de la misma masa central, T² es proporcional a a³. El periodo que falta es el conocido por (a₂/a₁) elevado a 3/2. Usa una unidad para ambos periodos y otra para ambos semiejes.','Pour deux orbites autour de la même masse centrale, T² est proportionnel à a³. La période manquante est la période connue fois (a₂/a₁) puissance 3/2. Une unité pour les deux périodes et une pour les deux axes.'),formula:'T₂ = T₁ (a₂ / a₁)^(3/2)',substitution:'{T1} × ({a2} / {a1})^(3/2)',fields:[F('T1','orbitPeriod','T₁','',1,'positive'),F('a1','orbitAxis','a₁','',1,'positive'),F('a2','otherAxis','a₂','',4,'positive')],result:'T₂',unit:''},
{id:'phys-kepler-axis',group:'forces',title:T('Kepler semi-major axis from the period','Kepler-Halbachse aus der Periode','Semieje mayor de Kepler a partir del periodo','Demi-grand axe de Kepler à partir de la période'),note:T('Rearrange T² ∝ a³ to the missing semi-major axis: a₂ = a₁ (T₂/T₁) to the power 2/3. Both orbits share the same central mass.','Stelle T² ∝ a³ nach der fehlenden großen Halbachse um: a₂ = a₁ (T₂/T₁) hoch 2/3. Beide Bahnen haben dieselbe Zentralmasse.','Despeja T² ∝ a³ para el semieje que falta: a₂ = a₁ (T₂/T₁) elevado a 2/3. Ambas órbitas comparten la misma masa central.','Réécris T² ∝ a³ pour le demi-grand axe manquant : a₂ = a₁ (T₂/T₁) puissance 2/3. Les deux orbites ont la même masse centrale.'),formula:'a₂ = a₁ (T₂ / T₁)^(2/3)',substitution:'{a1} × ({T2} / {T1})^(2/3)',fields:[F('a1','orbitAxis','a₁','',1,'positive'),F('T1','orbitPeriod','T₁','',1,'positive'),F('T2','otherPeriod','T₂','',8,'positive')],result:'a₂',unit:''},
{id:'phys-hooke',group:'forces',title:T('Force in the linear extension region','Kraft im linearen Dehnungsbereich','Fuerza en la zona de alargamiento lineal','Force dans le domaine d’allongement linéaire'),note:T('In the linear region the force is proportional to the extension: F = D x. D is the force per unit extension.','Im linearen Bereich ist die Kraft proportional zur Längenänderung: F = D x. D ist die Kraft je Längeneinheit.','En la zona lineal la fuerza es proporcional al alargamiento: F = D x. D es la fuerza por unidad de alargamiento.','Dans le domaine linéaire, la force est proportionnelle à l’allongement : F = D x. D est la force par unité d’allongement.'),formula:'F = D x',substitution:'{D} × {x}',fields:[F('D','stiffness','D','N/m',20,'positive'),F('x','extension','x','m',0.05,'signed')],result:'F',unit:'N'},
{id:'phys-hydrostatic',group:'forces',title:T('Pressure in a liquid column','Druck in einer Flüssigkeitssäule','Presión en una columna de líquido','Pression dans une colonne de liquide'),note:T('The pressure due to a liquid column is density times free-fall acceleration times depth.','Der Druck einer Flüssigkeitssäule ist Dichte mal Fallbeschleunigung mal Tiefe.','La presión de una columna de líquido es densidad por aceleración de caída por profundidad.','La pression d’une colonne de liquide est masse volumique fois accélération de chute fois profondeur.'),formula:'p = ρ g h',substitution:'{rho} × {g} × {h}',fields:[F('rho','density','ρ','kg/m³',1000,'positive'),F('g','gravity','g','m/s²',9.81,'positive'),F('h','depth','h','m',2,'nonnegative')],result:'p',unit:'Pa'},
{id:'phys-buoyancy',group:'forces',title:T('Buoyant force','Auftriebskraft','Empuje','Poussée d’Archimède'),note:T('The upward force equals the weight of the fluid displaced: density times volume times free-fall acceleration.','Die nach oben gerichtete Kraft entspricht dem Gewicht der verdrängten Flüssigkeit: Dichte mal Volumen mal Fallbeschleunigung.','La fuerza hacia arriba es el peso del fluido desplazado: densidad por volumen por aceleración de caída.','La force vers le haut égale le poids du fluide déplacé : masse volumique fois volume fois accélération de chute.'),formula:'F = ρ V g',substitution:'{rho} × {V} × {g}',fields:[F('rho','density','ρ','kg/m³',1000,'positive'),F('V','volume','V','m³',0.002,'nonnegative'),F('g','gravity','g','m/s²',9.81,'positive')],result:'F',unit:'N'},
{id:'phys-kinetic',group:'mechanical',title:T('Kinetic energy','Kinetische Energie','Energía cinética','Énergie cinétique'),note:T('The kinetic energy of a body is one half of mass times speed squared.','Die kinetische Energie eines Körpers ist die Hälfte aus Masse mal Geschwindigkeit zum Quadrat.','La energía cinética de un cuerpo es la mitad de la masa por la rapidez al cuadrado.','L’énergie cinétique d’un corps est la moitié de la masse fois la vitesse au carré.'),formula:'E = ½ m v²',substitution:'0.5 × {m} × {v}²',fields:[F('m','mass','m','kg',2,'positive'),F('v','speed','v','m/s',3,'signed')],result:'E',unit:'J'},
{id:'phys-height',group:'mechanical',title:T('Gravitational energy','Höhenenergie','Energía de altura','Énergie de hauteur'),note:T('The gravitational energy relative to a chosen zero level is mass times free-fall acceleration times height.','Die Höhenenergie gegenüber einem gewählten Nullniveau ist Masse mal Fallbeschleunigung mal Höhe.','La energía de altura respecto de un nivel cero elegido es masa por aceleración de caída por altura.','L’énergie de hauteur par rapport à un niveau zéro choisi est masse fois accélération de chute fois hauteur.'),formula:'E = m g h',substitution:'{m} × {g} × {h}',fields:[F('m','mass','m','kg',2,'positive'),F('g','gravity','g','m/s²',9.81,'positive'),F('h','height','h','m',5,'signed')],result:'E',unit:'J'},
{id:'phys-work',group:'mechanical',title:T('Work','Arbeit','Trabajo','Travail'),note:T('When the force is constant and along the path, the work is force times distance.','Bei konstanter Kraft längs des Weges ist die Arbeit Kraft mal Weg.','Si la fuerza es constante y sigue el camino, el trabajo es fuerza por distancia.','Lorsque la force est constante et dirigée le long du trajet, le travail est force fois distance.'),formula:'W = F s',substitution:'{F} × {s}',fields:[F('F','force','F','N',10,'signed'),F('s','path','s','m',3,'signed')],result:'W',unit:'J'},
{id:'phys-power',group:'mechanical',title:T('Power','Leistung','Potencia','Puissance'),note:T('Power is the energy transferred divided by the time taken.','Die Leistung ist die übertragene Energie geteilt durch die benötigte Zeit.','La potencia es la energía transferida dividida entre el tiempo empleado.','La puissance est l’énergie transférée divisée par la durée.'),formula:'P = W / Δt',substitution:'{W} / {t}',fields:[F('W','energy','W','J',30,'signed'),F('t','duration','Δt','s',6,'positive')],result:'P',unit:'W'},
{id:'phys-drop-speed',group:'mechanical',title:T('Speed from a change of height','Geschwindigkeit aus einer Höhenänderung','Rapidez a partir de un cambio de altura','Vitesse à partir d’un changement de hauteur'),note:T('If kinetic energy and gravitational energy exchange and nothing else changes, a body that starts from rest reaches v = √(2gh).','Wenn sich kinetische Energie und Höhenenergie austauschen und sonst nichts sich ändert, erreicht ein aus der Ruhe startender Körper v = √(2gh).','Si la energía cinética y la de altura se intercambian y nada más cambia, un cuerpo que parte del reposo alcanza v = √(2gh).','Si l’énergie cinétique et l’énergie de hauteur s’échangent et que rien d’autre ne change, un corps partant du repos atteint v = √(2gh).'),formula:'v = √(2 g h)',substitution:'√(2 × {g} × {h})',fields:[F('g','gravity','g','m/s²',9.81,'positive'),F('h','height','h','m',5,'nonnegative')],result:'v',unit:'m/s'},
{id:'phys-momentum',group:'mechanical',title:T('Momentum','Impuls','Momento lineal','Quantité de mouvement'),note:T('Momentum is mass times velocity. Keep a sign for the direction along one line.','Der Impuls ist Masse mal Geschwindigkeit. Behalte ein Vorzeichen für die Richtung auf einer Geraden.','El momento es masa por velocidad. Conserva un signo para la dirección sobre una recta.','La quantité de mouvement est masse fois vitesse. Garde un signe pour la direction sur une droite.'),formula:'p = m v',substitution:'{m} × {v}',fields:[F('m','mass','m','kg',2,'positive'),F('v','speed','v','m/s',3,'signed')],result:'p',unit:'kg·m/s'},
{id:'phys-collision',group:'mechanical',title:T('One-dimensional inelastic collision','Eindimensionaler unelastischer Stoß','Choque inelástico unidimensional','Choc inélastique unidimensionnel'),note:T('When two bodies stick together, momentum conservation gives the common speed (m₁u₁ + m₂u₂) / (m₁ + m₂).','Wenn zwei Körper zusammenhaften, liefert die Impulserhaltung die gemeinsame Geschwindigkeit (m₁u₁ + m₂u₂) / (m₁ + m₂).','Si dos cuerpos quedan unidos, la conservación del momento da la rapidez común (m₁u₁ + m₂u₂) / (m₁ + m₂).','Lorsque deux corps restent liés, la conservation de la quantité de mouvement donne la vitesse commune (m₁u₁ + m₂u₂) / (m₁ + m₂).'),formula:'v = (m₁u₁ + m₂u₂) / (m₁ + m₂)',substitution:'({m1} × {u1} + {m2} × {u2}) / ({m1} + {m2})',fields:[F('m1','mass1','m₁','kg',2,'positive'),F('u1','speed1','u₁','m/s',3,'signed'),F('m2','mass2','m₂','kg',1,'positive'),F('u2','speed2','u₂','m/s',0,'signed')],result:'v',unit:'m/s'},
{id:'phys-pendulum',group:'mechanical',title:T('Pendulum periods and length','Periodendauer und Länge eines Fadenpendels','Periodo y longitud de un péndulo','Période et longueur d’un pendule'),note:T('For small swings the square of the period is proportional to the length, so T₂ = T₁ √(ℓ₂/ℓ₁).','Bei kleinen Auslenkungen ist das Quadrat der Periodendauer proportional zur Länge, also T₂ = T₁ √(ℓ₂/ℓ₁).','Para oscilaciones pequeñas, el cuadrado del periodo es proporcional a la longitud, así que T₂ = T₁ √(ℓ₂/ℓ₁).','Pour de petites oscillations, le carré de la période est proportionnel à la longueur, donc T₂ = T₁ √(ℓ₂/ℓ₁).'),formula:'T₂ = T₁ √(ℓ₂ / ℓ₁)',substitution:'{T1} × √({l2} / {l1})',fields:[F('T1','period1','T₁','s',2,'positive'),F('l1','length1','ℓ₁','m',1,'positive'),F('l2','length2','ℓ₂','m',4,'positive')],result:'T₂',unit:'s'},
{id:'phys-ohm',group:'current',title:T('Electrical resistance','Elektrischer Widerstand','Resistencia eléctrica','Résistance électrique'),note:T('Resistance is voltage divided by current. This definition is for the chosen operating point.','Der Widerstand ist Spannung geteilt durch Stromstärke. Diese Definition gilt für den gewählten Arbeitspunkt.','La resistencia es tensión dividida entre intensidad. Esta definición vale para el punto de funcionamiento elegido.','La résistance est tension divisée par courant. Cette définition vaut pour le point de fonctionnement choisi.'),formula:'R = U / I',substitution:'{U} / {I}',fields:[F('U','voltage','U','V',6,'signed'),F('I','current','I','A',2,'nonzero')],result:'R',unit:'Ω'},
{id:'phys-ohm-current',group:'current',title:T('Current from resistance','Stromstärke aus dem Widerstand','Intensidad a partir de la resistencia','Courant à partir de la résistance'),note:T('Rearrange the resistance definition: current is voltage divided by resistance.','Stelle die Widerstandsdefinition um: die Stromstärke ist Spannung geteilt durch Widerstand.','Despeja la definición de resistencia: la intensidad es tensión dividida entre resistencia.','Isole la définition de la résistance : le courant est tension divisée par résistance.'),formula:'I = U / R',substitution:'{U} / {R}',fields:[F('U','voltage','U','V',6,'signed'),F('R','resistance','R','Ω',3,'nonzero')],result:'I',unit:'A'},
{id:'phys-current-charge',group:'current',title:T('Current and charge','Stromstärke und Ladung','Intensidad y carga','Courant et charge'),note:T('Current is the charge passing a point divided by the time taken.','Die Stromstärke ist die durch einen Punkt fließende Ladung geteilt durch die Zeit.','La intensidad es la carga que pasa por un punto dividida entre el tiempo.','Le courant est la charge qui passe en un point divisée par la durée.'),formula:'I = Q / Δt',substitution:'{Q} / {t}',fields:[F('Q','charge','Q','C',10,'signed'),F('t','duration','Δt','s',2,'positive')],result:'I',unit:'A'},
{id:'phys-elementary',group:'current',title:T('Charge as a multiple of the elementary charge','Ladung als Vielfaches der Elementarladung','Carga como múltiplo de la carga elemental','Charge comme multiple de la charge élémentaire'),note:T('A charge made of N elementary charges is Q = N e. e is the elementary charge.','Eine Ladung aus N Elementarladungen ist Q = N e. e ist die Elementarladung.','Una carga formada por N cargas elementales es Q = N e. e es la carga elemental.','Une charge formée de N charges élémentaires est Q = N e. e est la charge élémentaire.'),formula:'Q = N e',substitution:'{N} × e',fields:[F('N','count','N','',2,'signed')],result:'Q',unit:'C',constants:T('e = 1.602176634 × 10⁻¹⁹ C.','e = 1,602176634 × 10⁻¹⁹ C.','e = 1,602176634 × 10⁻¹⁹ C.','e = 1,602176634 × 10⁻¹⁹ C.')},
{id:'phys-electric-power',group:'current',title:T('Electrical power','Elektrische Leistung','Potencia eléctrica','Puissance électrique'),note:T('Electrical power is voltage times current.','Die elektrische Leistung ist Spannung mal Stromstärke.','La potencia eléctrica es tensión por intensidad.','La puissance électrique est tension fois courant.'),formula:'P = U I',substitution:'{U} × {I}',fields:[F('U','voltage','U','V',12,'signed'),F('I','current','I','A',0.5,'signed')],result:'P',unit:'W'},
{id:'phys-electric-energy',group:'current',title:T('Electrical energy','Elektrische Energie','Energía eléctrica','Énergie électrique'),note:T('At constant voltage and current, the energy transferred is voltage times current times time.','Bei konstanter Spannung und Stromstärke ist die übertragene Energie Spannung mal Stromstärke mal Zeit.','Con tensión e intensidad constantes, la energía transferida es tensión por intensidad por tiempo.','À tension et courant constants, l’énergie transférée est tension fois courant fois durée.'),formula:'E = U I t',substitution:'{U} × {I} × {t}',fields:[F('U','voltage','U','V',12,'signed'),F('I','current','I','A',0.5,'signed'),F('t','duration','t','s',10,'nonnegative')],result:'E',unit:'J'},
{id:'phys-efficiency',group:'current',title:T('Efficiency','Wirkungsgrad','Rendimiento','Rendement'),note:T('Efficiency compares the useful power with the supplied power. It cannot exceed 1.','Der Wirkungsgrad vergleicht die genutzte Leistung mit der aufgenommenen Leistung. Er kann 1 nicht überschreiten.','El rendimiento compara la potencia útil con la suministrada. No puede superar 1.','Le rendement compare la puissance utile à la puissance fournie. Il ne peut pas dépasser 1.'),formula:'η = Pₙ / Pₐ',substitution:'{useful} / {supplied}',fields:[F('useful','usefulPower','Pₙ','W',40,'nonnegative'),F('supplied','suppliedPower','Pₐ','W',50,'positive')],result:'η',unit:''},
{id:'phys-series',group:'current',title:T('Resistances in series','Widerstände in Reihe','Resistencias en serie','Résistances en série'),note:T('In a series path the same current passes each resistor, and the voltages add, so the resistances add.','In einem Reihenzweig fließt dieselbe Stromstärke durch jeden Widerstand, und die Spannungen addieren sich, also addieren sich die Widerstände.','En un camino en serie pasa la misma intensidad por cada resistor y las tensiones se suman, así que las resistencias se suman.','Dans un chemin en série, le même courant traverse chaque résistance et les tensions s’additionnent, donc les résistances s’additionnent.'),formula:'R = R₁ + R₂ + R₃',substitution:'{R1} + {R2} + {R3}',fields:[F('R1','resistance','R₁','Ω',2,'nonnegative'),F('R2','resistance2','R₂','Ω',3,'nonnegative'),F('R3','resistance3','R₃','Ω',5,'nonnegative')],result:'R',unit:'Ω'},
{id:'phys-parallel',group:'current',title:T('Two resistances in parallel','Zwei Widerstände parallel','Dos resistencias en paralelo','Deux résistances en parallèle'),note:T('In parallel the voltage is the same and the currents add, so 1/R = 1/R₁ + 1/R₂.','Parallel liegt dieselbe Spannung an und die Stromstärken addieren sich, also gilt 1/R = 1/R₁ + 1/R₂.','En paralelo la tensión es la misma y las intensidades se suman, así que 1/R = 1/R₁ + 1/R₂.','En parallèle la tension est la même et les courants s’additionnent, donc 1/R = 1/R₁ + 1/R₂.'),formula:'R = 1 / (1/R₁ + 1/R₂)',substitution:'1 / (1/{R1} + 1/{R2})',fields:[F('R1','resistance','R₁','Ω',6,'positive'),F('R2','resistance2','R₂','Ω',3,'positive')],result:'R',unit:'Ω'},
{id:'phys-reflection',group:'optics',title:T('Law of reflection','Reflexionsgesetz','Ley de la reflexión','Loi de la réflexion'),note:T('The angle of reflection equals the angle of incidence, both measured from the normal.','Der Reflexionswinkel ist gleich dem Einfallswinkel, beide vom Lot aus gemessen.','El ángulo de reflexión es igual al de incidencia, ambos medidos desde la normal.','L’angle de réflexion est égal à l’angle d’incidence, tous deux mesurés depuis la normale.'),formula:'θᵣ = θᵢ',substitution:'{theta}',fields:[F('theta','incidence','θᵢ','°',35,'nonnegative')],result:'θᵣ',unit:'°'},
{id:'phys-snell-angle2',group:'optics',title:T('Snell’s law, angle in the second medium','Snellius-Gesetz, Winkel im zweiten Medium','Ley de Snell, ángulo en el segundo medio','Loi de Snell, angle dans le second milieu'),note:T('Angles are measured from the normal. n₁ sin θ₁ = n₂ sin θ₂. If n₁ sin θ₁ exceeds n₂, there is no real refracted angle.','Die Winkel werden vom Lot aus gemessen. n₁ sin θ₁ = n₂ sin θ₂. Übersteigt n₁ sin θ₁ die Brechzahl n₂, gibt es keinen reellen Brechungswinkel.','Los ángulos se miden desde la normal. n₁ sin θ₁ = n₂ sin θ₂. Si n₁ sin θ₁ supera a n₂, no hay un ángulo de refracción real.','Les angles se mesurent depuis la normale. n₁ sin θ₁ = n₂ sin θ₂. Si n₁ sin θ₁ dépasse n₂, il n’y a pas d’angle de réfraction réel.'),formula:'θ₂ = arcsin((n₁ / n₂) sin θ₁)',substitution:'arcsin(({n1} / {n2}) × sin({theta1}°))',fields:[F('n1','index1','n₁','',1,'positive'),F('theta1','angle1','θ₁','°',30,'nonnegative'),F('n2','index2','n₂','',1.5,'positive')],result:'θ₂',unit:'°'},
{id:'phys-snell-angle1',group:'optics',title:T('Snell’s law, angle in the first medium','Snellius-Gesetz, Winkel im ersten Medium','Ley de Snell, ángulo en el primer medio','Loi de Snell, angle dans le premier milieu'),note:T('The same product n sin θ fixes the missing angle. The sample continues the ray that entered glass from air at 30°.','Dasselbe Produkt n sin θ bestimmt den fehlenden Winkel. Das Beispiel setzt den Strahl fort, der aus Luft unter 30° in Glas eintritt.','El mismo producto n sin θ fija el ángulo que falta. El ejemplo continúa el rayo que entra en el vidrio desde el aire a 30°.','Le même produit n sin θ fixe l’angle manquant. L’exemple prolonge le rayon qui entre dans le verre depuis l’air à 30°.'),formula:'θ₁ = arcsin((n₂ / n₁) sin θ₂)',substitution:'arcsin(({n2} / {n1}) × sin({theta2}°))',fields:[F('n2','index2','n₂','',1.5,'positive'),F('theta2','angle2','θ₂','°',19.47122063449069,'nonnegative'),F('n1','index1','n₁','',1,'positive')],result:'θ₁',unit:'°'},
{id:'phys-snell-n2',group:'optics',title:T('Snell’s law, second refractive index','Snellius-Gesetz, zweite Brechzahl','Ley de Snell, segundo índice','Loi de Snell, second indice'),note:T('Divide the first product n₁ sin θ₁ by sin θ₂. Both angles must be greater than 0° so the sines are not zero.','Teile das erste Produkt n₁ sin θ₁ durch sin θ₂. Beide Winkel müssen größer als 0° sein, damit die Sinuswerte nicht null sind.','Divide el primer producto n₁ sin θ₁ entre sin θ₂. Ambos ángulos deben ser mayores que 0° para que los senos no sean cero.','Divise le premier produit n₁ sin θ₁ par sin θ₂. Les deux angles doivent être supérieurs à 0° pour que les sinus ne soient pas nuls.'),formula:'n₂ = n₁ sin θ₁ / sin θ₂',substitution:'{n1} × sin({theta1}°) / sin({theta2}°)',fields:[F('n1','index1','n₁','',1,'positive'),F('theta1','angle1','θ₁','°',30,'positive'),F('theta2','angle2','θ₂','°',19.47122063449069,'positive')],result:'n₂',unit:''},
{id:'phys-snell-n1',group:'optics',title:T('Snell’s law, first refractive index','Snellius-Gesetz, erste Brechzahl','Ley de Snell, primer índice','Loi de Snell, premier indice'),note:T('Divide n₂ sin θ₂ by sin θ₁. This is the same law, solved for the first index.','Teile n₂ sin θ₂ durch sin θ₁. Dasselbe Gesetz, aufgelöst nach der ersten Brechzahl.','Divide n₂ sin θ₂ entre sin θ₁. Es la misma ley, despejada para el primer índice.','Divise n₂ sin θ₂ par sin θ₁. C’est la même loi, résolue pour le premier indice.'),formula:'n₁ = n₂ sin θ₂ / sin θ₁',substitution:'{n2} × sin({theta2}°) / sin({theta1}°)',fields:[F('n2','index2','n₂','',1.5,'positive'),F('theta2','angle2','θ₂','°',19.47122063449069,'positive'),F('theta1','angle1','θ₁','°',30,'positive')],result:'n₁',unit:''},
{id:'phys-lens-image',group:'optics',title:T('Thin lens, image distance','Dünne Linse, Bildweite','Lente delgada, distancia de la imagen','Lentille mince, distance de l’image'),note:T('The thin-lens equation is 1/f = 1/u + 1/v. A positive sample is a real object, a converging lens and a real image. If u = f the image is not at a finite distance.','Die Gleichung der dünnen Linse lautet 1/f = 1/u + 1/v. Das positive Beispiel ist ein reeller Gegenstand, eine Sammellinse und ein reelles Bild. Bei u = f liegt das Bild nicht in endlichem Abstand.','La ecuación de la lente delgada es 1/f = 1/u + 1/v. El ejemplo positivo es un objeto real, una lente convergente y una imagen real. Si u = f, la imagen no está a una distancia finita.','L’équation de la lentille mince est 1/f = 1/u + 1/v. L’exemple positif est un objet réel, une lentille convergente et une image réelle. Si u = f, l’image n’est pas à distance finie.'),formula:'v = u f / (u − f)',substitution:'{u} × {f} / ({u} − {f})',fields:[F('u','objectDistance','u','m',0.3,'nonzero'),F('f','focal','f','m',0.1,'nonzero')],result:'v',unit:'m'},
{id:'phys-lens-object',group:'optics',title:T('Thin lens, object distance','Dünne Linse, Gegenstandsweite','Lente delgada, distancia del objeto','Lentille mince, distance de l’objet'),note:T('Solved for the object distance, u = v f / (v − f). The same sign convention as the image-distance card. v = f has no finite object distance.','Aufgelöst nach der Gegenstandsweite: u = v f / (v − f). Dieselbe Vorzeichenvereinbarung wie bei der Bildweite. Bei v = f gibt es keine endliche Gegenstandsweite.','Despejada para la distancia del objeto, u = v f / (v − f). El mismo convenio de signos que en la distancia de la imagen. Si v = f, no hay una distancia de objeto finita.','Résolue pour la distance de l’objet, u = v f / (v − f). La même convention de signe que pour la distance de l’image. Si v = f, il n’y a pas de distance d’objet finie.'),formula:'u = v f / (v − f)',substitution:'{v} × {f} / ({v} − {f})',fields:[F('v','imageDistance','v','m',0.15,'nonzero'),F('f','focal','f','m',0.1,'nonzero')],result:'u',unit:'m'},
{id:'phys-lens-focal',group:'optics',title:T('Thin lens, focal length','Dünne Linse, Brennweite','Lente delgada, distancia focal','Lentille mince, distance focale'),note:T('Solved for the focal length, f = u v / (u + v). If u + v = 0 the focal length is not finite.','Aufgelöst nach der Brennweite: f = u v / (u + v). Bei u + v = 0 ist die Brennweite nicht endlich.','Despejada para la distancia focal, f = u v / (u + v). Si u + v = 0, la distancia focal no es finita.','Résolue pour la distance focale, f = u v / (u + v). Si u + v = 0, la distance focale n’est pas finie.'),formula:'f = u v / (u + v)',substitution:'{u} × {v} / ({u} + {v})',fields:[F('u','objectDistance','u','m',0.3,'nonzero'),F('v','imageDistance','v','m',0.15,'nonzero')],result:'f',unit:'m'},
{id:'phys-fringe',group:'optics',title:T('Double-slit fringe spacing','Streifenabstand am Doppelspalt','Separación de franjas en la doble rendija','Interfrange de la double fente'),note:T('For a distant screen and a small angle, the fringe spacing is wavelength times screen distance divided by slit separation.','Bei fernem Schirm und kleinem Winkel ist der Streifenabstand Wellenlänge mal Schirmabstand geteilt durch den Spaltabstand.','Con una pantalla lejana y un ángulo pequeño, la separación de franjas es longitud de onda por distancia a la pantalla dividida entre la separación de rendijas.','Pour un écran lointain et un petit angle, l’interfrange est longueur d’onde fois distance à l’écran divisée par l’écartement des fentes.'),formula:'Δy = λ L / d',substitution:'{lambda} × {L} / {d}',fields:[F('lambda','wavelength','λ','m',5e-7,'positive'),F('L','screen','L','m',2,'positive'),F('d','slit','d','m',0.001,'positive')],result:'Δy',unit:'m'},
{id:'phys-path',group:'optics',title:T('Constructive path difference','Konstruktiver Gangunterschied','Diferencia de camino constructiva','Différence de marche constructive'),note:T('Constructive interference of two waves occurs when the path difference is a whole number of wavelengths.','Konstruktive Interferenz zweier Wellen tritt auf, wenn der Gangunterschied ein ganzzahliges Vielfaches der Wellenlänge ist.','La interferencia constructiva de dos ondas ocurre cuando la diferencia de camino es un número entero de longitudes de onda.','L’interférence constructive de deux ondes a lieu lorsque la différence de marche est un nombre entier de longueurs d’onde.'),formula:'δ = n λ',substitution:'{n} × {lambda}',fields:[F('n','order','n','',2,'whole'),F('lambda','wavelength','λ','m',5e-7,'positive')],result:'δ',unit:'m'},
{id:'phys-bragg',group:'optics',title:T('Bragg condition','Bragg-Bedingung','Condición de Bragg','Condition de Bragg'),note:T('Constructive reflection from parallel layers follows nλ = 2d sin θ. This card returns the wavelength.','Konstruktive Reflexion an parallelen Schichten folgt nλ = 2d sin θ. Diese Karte gibt die Wellenlänge aus.','La reflexión constructiva en planos paralelos sigue nλ = 2d sin θ. Esta tarjeta devuelve la longitud de onda.','La réflexion constructive sur des plans parallèles suit nλ = 2d sin θ. Cette fiche renvoie la longueur d’onde.'),formula:'λ = 2 d sin θ / n',substitution:'2 × {d} × sin({theta}°) / {n}',fields:[F('d','spacing','d','m',2e-10,'positive'),F('theta','angle','θ','°',30,'positive'),F('n','order','n','',1,'integer')],result:'λ',unit:'m'},
{id:'phys-heat',group:'heat',title:T('Heat and temperature change','Wärme und Temperaturänderung','Calor y cambio de temperatura','Chaleur et variation de température'),note:T('The heat linked to a temperature change, without a change of state, is specific heat capacity times mass times the temperature change.','Die mit einer Temperaturänderung verbundene Wärme, ohne Aggregatzustandswechsel, ist spezifische Wärmekapazität mal Masse mal Temperaturänderung.','El calor ligado a un cambio de temperatura, sin cambio de estado, es capacidad calorífica específica por masa por el cambio de temperatura.','La chaleur liée à une variation de température, sans changement d’état, est capacité thermique massique fois masse fois variation de température.'),formula:'Q = c m ΔT',substitution:'{c} × {m} × {dT}',fields:[F('c','heatCapacity','c','J/(kg·K)',4180,'positive'),F('m','mass','m','kg',0.2,'positive'),F('dT','temperatureChange','ΔT','K',5,'signed')],result:'Q',unit:'J'},
{id:'phys-gas-pressure',group:'heat',title:T('Ideal gas, pressure','Ideales Gas, Druck','Gas ideal, presión','Gaz parfait, pression'),note:T('For an ideal gas, P V = n R T. Pressure is n R T / V. T is the absolute temperature, and the volume must be positive.','Für ein ideales Gas gilt P V = n R T. Der Druck ist n R T / V. T ist die absolute Temperatur, das Volumen muss positiv sein.','Para un gas ideal, P V = n R T. La presión es n R T / V. T es la temperatura absoluta y el volumen debe ser positivo.','Pour un gaz parfait, P V = n R T. La pression est n R T / V. T est la température absolue, et le volume doit être positif.'),formula:'P = n R T / V',substitution:'{n} × R × {T} / {V}',fields:[F('n','amount','n','mol',1,'positive'),F('T','temperature','T','K',300,'positive'),F('V','gasVolume','V','m³',0.025,'positive')],result:'P',unit:'Pa',constants:T('R = 8.314462618 J/(mol·K).','R = 8,314462618 J/(mol·K).','R = 8,314462618 J/(mol·K).','R = 8,314462618 J/(mol·K).')},
{id:'phys-gas-volume',group:'heat',title:T('Ideal gas, volume','Ideales Gas, Volumen','Gas ideal, volumen','Gaz parfait, volume'),note:T('Solved for the volume, V = n R T / P. A zero or negative volume is rejected, and so is a temperature at or below absolute zero.','Aufgelöst nach dem Volumen: V = n R T / P. Ein Volumen von null oder darunter wird abgelehnt, ebenso eine Temperatur bei oder unter dem absoluten Nullpunkt.','Despejada para el volumen, V = n R T / P. Se rechaza un volumen nulo o negativo, y también una temperatura en el cero absoluto o por debajo.','Résolue pour le volume, V = n R T / P. Un volume nul ou négatif est refusé, de même qu’une température au zéro absolu ou en dessous.'),formula:'V = n R T / P',substitution:'{n} × R × {T} / {P}',fields:[F('n','amount','n','mol',1,'positive'),F('T','temperature','T','K',300,'positive'),F('P','pressure','P','Pa',99773.551416,'positive')],result:'V',unit:'m³',constants:T('R = 8.314462618 J/(mol·K).','R = 8,314462618 J/(mol·K).','R = 8,314462618 J/(mol·K).','R = 8,314462618 J/(mol·K).')},
{id:'phys-gas-amount',group:'heat',title:T('Ideal gas, amount','Ideales Gas, Stoffmenge','Gas ideal, cantidad','Gaz parfait, quantité'),note:T('Solved for the amount of gas, n = P V / (R T). Use pascal, cubic metres and kelvin with this value of R.','Aufgelöst nach der Stoffmenge: n = P V / (R T). Mit diesem R in Pascal, Kubikmetern und Kelvin rechnen.','Despejada para la cantidad de gas, n = P V / (R T). Con este valor de R, usa pascal, metros cúbicos y kelvin.','Résolue pour la quantité de gaz, n = P V / (R T). Avec cette valeur de R, utilise le pascal, le mètre cube et le kelvin.'),formula:'n = P V / (R T)',substitution:'{P} × {V} / (R × {T})',fields:[F('P','pressure','P','Pa',99773.551416,'positive'),F('V','gasVolume','V','m³',0.025,'positive'),F('T','temperature','T','K',300,'positive')],result:'n',unit:'mol',constants:T('R = 8.314462618 J/(mol·K).','R = 8,314462618 J/(mol·K).','R = 8,314462618 J/(mol·K).','R = 8,314462618 J/(mol·K).')},
{id:'phys-gas-temperature',group:'heat',title:T('Ideal gas, temperature','Ideales Gas, Temperatur','Gas ideal, temperatura','Gaz parfait, température'),note:T('Solved for the absolute temperature, T = P V / (n R). The result must lie above absolute zero.','Aufgelöst nach der absoluten Temperatur: T = P V / (n R). Das Ergebnis muss über dem absoluten Nullpunkt liegen.','Despejada para la temperatura absoluta, T = P V / (n R). El resultado debe estar por encima del cero absoluto.','Résolue pour la température absolue, T = P V / (n R). Le résultat doit être au-dessus du zéro absolu.'),formula:'T = P V / (n R)',substitution:'{P} × {V} / ({n} × R)',fields:[F('P','pressure','P','Pa',99773.551416,'positive'),F('V','gasVolume','V','m³',0.025,'positive'),F('n','amount','n','mol',1,'positive')],result:'T',unit:'K',constants:T('R = 8.314462618 J/(mol·K).','R = 8,314462618 J/(mol·K).','R = 8,314462618 J/(mol·K).','R = 8,314462618 J/(mol·K).')},
{id:'phys-conduction',group:'heat',title:T('Heat flow by conduction','Wärmestrom durch Leitung','Flujo de calor por conducción','Flux de chaleur par conduction'),note:T('Through a slab, the conducted power is conductivity times area times temperature difference, divided by thickness.','Durch eine Schicht ist die geleitete Leistung Leitfähigkeit mal Fläche mal Temperaturdifferenz, geteilt durch die Dicke.','A través de una lámina, la potencia conducida es conductividad por área por diferencia de temperatura, dividida entre el espesor.','À travers une paroi, la puissance conduite est conductivité fois aire fois écart de température, divisée par l’épaisseur.'),formula:'P = λ A ΔT / d',substitution:'{lambda} × {A} × {dT} / {d}',fields:[F('lambda','conductivity','λ','W/(m·K)',0.04,'positive'),F('A','area','A','m²',10,'positive'),F('dT','temperatureChange','ΔT','K',20,'signed'),F('d','thickness','d','m',0.1,'positive')],result:'P',unit:'W'},
{id:'phys-wien',group:'heat',title:T('Wien displacement','Wiensches Verschiebungsgesetz','Ley de desplazamiento de Wien','Loi du déplacement de Wien'),note:T('The wavelength of maximum emission of a hot surface is the Wien constant divided by the absolute temperature.','Die Wellenlänge maximaler Emission einer heißen Oberfläche ist die Wien-Konstante geteilt durch die absolute Temperatur.','La longitud de onda de emisión máxima de una superficie caliente es la constante de Wien dividida entre la temperatura absoluta.','La longueur d’onde d’émission maximale d’une surface chaude est la constante de Wien divisée par la température absolue.'),formula:'λₘ = b / T',substitution:'b / {T}',fields:[F('T','temperature','T','K',5800,'positive')],result:'λₘ',unit:'m',constants:T('b = 2.897771955 × 10⁻³ m·K.','b = 2,897771955 × 10⁻³ m·K.','b = 2,897771955 × 10⁻³ m·K.','b = 2,897771955 × 10⁻³ m·K.')},
{id:'phys-stefan',group:'heat',title:T('Stefan–Boltzmann radiation','Stefan-Boltzmann-Strahlung','Radiación de Stefan–Boltzmann','Rayonnement de Stefan–Boltzmann'),note:T('A black surface radiates power σ A T⁴. σ is the Stefan–Boltzmann constant and T is the absolute temperature.','Eine schwarze Fläche strahlt die Leistung σ A T⁴ ab. σ ist die Stefan-Boltzmann-Konstante und T die absolute Temperatur.','Una superficie negra radia la potencia σ A T⁴. σ es la constante de Stefan–Boltzmann y T la temperatura absoluta.','Une surface noire rayonne la puissance σ A T⁴. σ est la constante de Stefan–Boltzmann et T la température absolue.'),formula:'P = σ A T⁴',substitution:'σ × {A} × {T}⁴',fields:[F('A','area','A','m²',1,'positive'),F('T','temperature','T','K',300,'positive')],result:'P',unit:'W',constants:T('σ = 5.670374419 × 10⁻⁸ W/(m²·K⁴).','σ = 5,670374419 × 10⁻⁸ W/(m²·K⁴).','σ = 5,670374419 × 10⁻⁸ W/(m²·K⁴).','σ = 5,670374419 × 10⁻⁸ W/(m²·K⁴).')},
{id:'phys-flux',group:'induction',title:T('Magnetic flux','Magnetischer Fluss','Flujo magnético','Flux magnétique'),note:T('For a uniform field perpendicular to a flat area, the flux is flux density times area.','Für ein homogenes Feld senkrecht zu einer ebenen Fläche ist der Fluss Flussdichte mal Fläche.','Para un campo uniforme perpendicular a un área plana, el flujo es densidad de flujo por área.','Pour un champ uniforme perpendiculaire à une surface plane, le flux est densité de flux fois aire.'),formula:'Φ = B A',substitution:'{B} × {A}',fields:[F('B','field','B','T',0.2,'signed'),F('A','area','A','m²',0.05,'nonnegative')],result:'Φ',unit:'Wb'},
{id:'phys-induction',group:'induction',title:T('Induced voltage','Induktionsspannung','Tensión inducida','Tension induite'),note:T('The magnitude of the induced voltage is the number of turns times the flux change divided by the time.','Der Betrag der Induktionsspannung ist Windungszahl mal Flussänderung geteilt durch die Zeit.','La magnitud de la tensión inducida es el número de espiras por el cambio de flujo dividido entre el tiempo.','La valeur de la tension induite est le nombre de spires fois la variation de flux divisée par la durée.'),formula:'|U| = N |ΔΦ| / Δt',substitution:'{N} × |{dPhi}| / {t}',fields:[F('N','turns','N','',100,'integer'),F('dPhi','fluxChange','ΔΦ','Wb',0.01,'signed'),F('t','duration','Δt','s',0.02,'positive')],result:'|U|',unit:'V'},
{id:'phys-lorentz-charge',group:'induction',title:T('Force on a moving charge','Kraft auf eine bewegte Ladung','Fuerza sobre una carga en movimiento','Force sur une charge en mouvement'),note:T('When velocity and magnetic field are perpendicular, the force magnitude is charge times speed times flux density.','Wenn Geschwindigkeit und Magnetfeld senkrecht zueinander stehen, ist der Kraftbetrag Ladung mal Geschwindigkeit mal Flussdichte.','Cuando la velocidad y el campo magnético son perpendiculares, la fuerza es carga por rapidez por densidad de flujo.','Lorsque la vitesse et le champ magnétique sont perpendiculaires, la force vaut charge fois vitesse fois densité de flux.'),formula:'F = |q| v B',substitution:'{q} × {v} × {B}',fields:[F('q','particleCharge','|q|','C',1.602176634e-19,'nonnegative'),F('v','speed','v','m/s',1e6,'nonnegative'),F('B','field','B','T',0.1,'nonnegative')],result:'F',unit:'N'},
{id:'phys-lorentz-wire',group:'induction',title:T('Force on a current-carrying wire','Kraft auf einen stromdurchflossenen Leiter','Fuerza sobre un conductor con corriente','Force sur un fil parcouru par un courant'),note:T('When the wire is perpendicular to the field, the force is current times length times flux density.','Steht der Leiter senkrecht zum Feld, ist die Kraft Stromstärke mal Länge mal Flussdichte.','Si el conductor es perpendicular al campo, la fuerza es intensidad por longitud por densidad de flujo.','Si le fil est perpendiculaire au champ, la force est courant fois longueur fois densité de flux.'),formula:'F = I ℓ B',substitution:'{I} × {L} × {B}',fields:[F('I','current','I','A',2,'nonnegative'),F('L','wireLength','ℓ','m',0.3,'positive'),F('B','field','B','T',0.5,'nonnegative')],result:'F',unit:'N'},
{id:'phys-cyclotron',group:'induction',title:T('Radius of a charged particle in a magnetic field','Radius einer Ladung im Magnetfeld','Radio de una carga en un campo magnético','Rayon d’une charge dans un champ magnétique'),note:T('A charge moving perpendicular to a uniform field follows a circle of radius m v / (|q| B).','Eine Ladung, die senkrecht zu einem homogenen Feld fliegt, folgt einem Kreis mit Radius m v / (|q| B).','Una carga que se mueve perpendicular a un campo uniforme sigue un círculo de radio m v / (|q| B).','Une charge qui se déplace perpendiculairement à un champ uniforme suit un cercle de rayon m v / (|q| B).'),formula:'r = m v / (|q| B)',substitution:'{m} × {v} / ({q} × {B})',fields:[F('m','mass','m','kg',9.1093837e-31,'positive'),F('v','speed','v','m/s',1e6,'nonnegative'),F('q','particleCharge','|q|','C',1.602176634e-19,'positive'),F('B','field','B','T',0.01,'positive')],result:'r',unit:'m'},
{id:'phys-inductor',group:'induction',title:T('Voltage across an inductor','Spannung an einer Spule','Tensión en una bobina','Tension aux bornes d’une bobine'),note:T('The self-induced voltage magnitude is inductance times the current change divided by the time.','Der Betrag der Selbstinduktionsspannung ist Induktivität mal Stromänderung geteilt durch die Zeit.','La magnitud de la tensión autoinducida es inductancia por el cambio de intensidad dividido entre el tiempo.','La valeur de la tension auto-induite est inductance fois variation de courant divisée par la durée.'),formula:'|U| = L |ΔI| / Δt',substitution:'{L} × |{dI}| / {t}',fields:[F('L','inductance','L','H',0.2,'positive'),F('dI','currentChange','ΔI','A',1,'signed'),F('t','duration','Δt','s',0.01,'positive')],result:'|U|',unit:'V'},
{id:'phys-coil-energy',group:'induction',title:T('Energy in an inductor','Energie einer Spule','Energía de una bobina','Énergie d’une bobine'),note:T('The energy stored in the magnetic field of an inductor is one half of inductance times current squared.','Die im Magnetfeld einer Spule gespeicherte Energie ist die Hälfte aus Induktivität mal Stromstärke zum Quadrat.','La energía almacenada en el campo magnético de una bobina es la mitad de la inductancia por la intensidad al cuadrado.','L’énergie stockée dans le champ magnétique d’une bobine est la moitié de l’inductance fois le courant au carré.'),formula:'W = ½ L I²',substitution:'0.5 × {L} × {I}²',fields:[F('L','inductance','L','H',0.2,'positive'),F('I','current','I','A',3,'signed')],result:'W',unit:'J'},
{id:'phys-coil-field',group:'induction',title:T('Field inside a long coil','Feld im Inneren einer langen Spule','Campo en el interior de una bobina larga','Champ à l’intérieur d’une longue bobine'),note:T('Inside a long coil the flux density is μ₀ times turns per length times current. μ₀ is the vacuum permeability.','Im Inneren einer langen Spule ist die Flussdichte μ₀ mal Windungen je Länge mal Stromstärke. μ₀ ist die magnetische Feldkonstante.','En el interior de una bobina larga, la densidad de flujo es μ₀ por espiras por unidad de longitud por intensidad. μ₀ es la permeabilidad del vacío.','À l’intérieur d’une longue bobine, la densité de flux est μ₀ fois spires par longueur fois courant. μ₀ est la perméabilité du vide.'),formula:'B = μ₀ N I / ℓ',substitution:'μ₀ × {N} × {I} / {L}',fields:[F('N','turns','N','',500,'integer'),F('I','current','I','A',2,'signed'),F('L','wireLength','ℓ','m',0.5,'positive')],result:'B',unit:'T',constants:T('μ₀ = 1.25663706212 × 10⁻⁶ N/A².','μ₀ = 1,25663706212 × 10⁻⁶ N/A².','μ₀ = 1,25663706212 × 10⁻⁶ N/A².','μ₀ = 1,25663706212 × 10⁻⁶ N/A².')},
{id:'phys-transformer-voltage',group:'induction',title:T('Ideal transformer, voltage','Idealer Transformator, Spannung','Transformador ideal, tensión','Transformateur idéal, tension'),note:T('For an ideal transformer the voltages are in the same ratio as the turns: U₂ = U₁ N₂/N₁.','Bei einem idealen Transformator stehen die Spannungen im selben Verhältnis wie die Windungen: U₂ = U₁ N₂/N₁.','En un transformador ideal, las tensiones están en la misma razón que las espiras: U₂ = U₁ N₂/N₁.','Pour un transformateur idéal, les tensions sont dans le même rapport que les spires : U₂ = U₁ N₂/N₁.'),formula:'U₂ = U₁ N₂ / N₁',substitution:'{U1} × {N2} / {N1}',fields:[F('U1','inputVoltage','U₁','V',230,'signed'),F('N1','turns1','N₁','',1000,'integer'),F('N2','turns2','N₂','',50,'integer')],result:'U₂',unit:'V'},
{id:'phys-transformer-current',group:'induction',title:T('Ideal transformer, current','Idealer Transformator, Stromstärke','Transformador ideal, intensidad','Transformateur idéal, courant'),note:T('Energy balance makes the current ratio the reverse of the voltage ratio: I₂ = I₁ N₁/N₂.','Die Energiebilanz macht das Stromverhältnis zum Kehrwert des Spannungsverhältnisses: I₂ = I₁ N₁/N₂.','El balance de energía invierte la razón de intensidades respecto de la de tensiones: I₂ = I₁ N₁/N₂.','Le bilan d’énergie inverse le rapport des courants par rapport à celui des tensions : I₂ = I₁ N₁/N₂.'),formula:'I₂ = I₁ N₁ / N₂',substitution:'{I1} × {N1} / {N2}',fields:[F('I1','inputCurrent','I₁','A',0.1,'signed'),F('N1','turns1','N₁','',1000,'integer'),F('N2','turns2','N₂','',50,'integer')],result:'I₂',unit:'A'},
{id:'phys-wave',group:'waves',title:T('Wave speed, frequency and wavelength','Phasengeschwindigkeit, Frequenz und Wellenlänge','Velocidad de fase, frecuencia y longitud de onda','Célérité, fréquence et longueur d’onde'),note:T('Phase speed is frequency times wavelength. The same relation describes an electromagnetic wave in vacuum when the speed is the speed of light.','Die Phasengeschwindigkeit ist Frequenz mal Wellenlänge. Dieselbe Beziehung beschreibt eine elektromagnetische Welle im Vakuum, wenn die Geschwindigkeit die Lichtgeschwindigkeit ist.','La velocidad de fase es frecuencia por longitud de onda. La misma relación describe una onda electromagnética en el vacío cuando la velocidad es la de la luz.','La célérité est fréquence fois longueur d’onde. La même relation décrit une onde électromagnétique dans le vide lorsque la vitesse est celle de la lumière.'),formula:'c = f λ',substitution:'{f} × {lambda}',fields:[F('f','frequency','f','Hz',100,'positive'),F('lambda','wavelength','λ','m',3,'positive')],result:'c',unit:'m/s'},
{id:'phys-thomson',group:'waves',title:T('Thomson period of an LC circuit','Thomson-Periodendauer eines LC-Kreises','Periodo de Thomson de un circuito LC','Période de Thomson d’un circuit LC'),note:T('The period of an ideal undamped LC oscillation is 2π times the square root of inductance times capacitance.','Die Periodendauer einer idealen ungedämpften LC-Schwingung ist 2π mal die Quadratwurzel aus Induktivität mal Kapazität.','El periodo de una oscilación LC ideal no amortiguada es 2π por la raíz cuadrada de inductancia por capacidad.','La période d’une oscillation LC idéale non amortie est 2π fois la racine carrée de l’inductance fois la capacité.'),formula:'T = 2π √(L C)',substitution:'2π × √({L} × {C})',fields:[F('L','inductance','L','H',0.01,'positive'),F('C','capacitance','C','F',1e-6,'positive')],result:'T',unit:'s'},
{id:'phys-rc',group:'waves',title:T('RC time constant','RC-Zeitkonstante','Constante de tiempo RC','Constante de temps RC'),note:T('The time constant of a series resistor and capacitor is resistance times capacitance.','Die Zeitkonstante aus Reihenwiderstand und Kondensator ist Widerstand mal Kapazität.','La constante de tiempo de un resistor y un condensador en serie es resistencia por capacidad.','La constante de temps d’une résistance et d’un condensateur en série est résistance fois capacité.'),formula:'τ = R C',substitution:'{R} × {C}',fields:[F('R','resistance','R','Ω',1000,'positive'),F('C','capacitance','C','F',1e-4,'positive')],result:'τ',unit:'s'},
{id:'phys-spring-period',group:'waves',title:T('Period of a spring-mass oscillator','Periodendauer eines Federpendels','Periodo de un oscilador masa-muelle','Période d’un oscillateur masse-ressort'),note:T('With a linear restoring force F = −Dx, the period is 2π times the square root of mass over D.','Bei einer linearen Rückstellkraft F = −Dx ist die Periodendauer 2π mal die Quadratwurzel aus Masse durch D.','Con una fuerza recuperadora lineal F = −Dx, el periodo es 2π por la raíz cuadrada de masa entre D.','Avec une force de rappel linéaire F = −Dx, la période est 2π fois la racine carrée de la masse sur D.'),formula:'T = 2π √(m / D)',substitution:'2π × √({m} / {D})',fields:[F('m','mass','m','kg',0.25,'positive'),F('D','stiffness','D','N/m',1,'positive')],result:'T',unit:'s'},
{id:'phys-field',group:'fields',title:T('Electric field strength','Elektrische Feldstärke','Intensidad del campo eléctrico','Champ électrique'),note:T('Field strength is defined as the force on a test charge divided by that charge.','Die Feldstärke ist definiert als die Kraft auf eine Probeladung geteilt durch diese Ladung.','La intensidad de campo se define como la fuerza sobre una carga de prueba dividida entre esa carga.','Le champ est défini comme la force sur une charge d’épreuve divisée par cette charge.'),formula:'E = F / q',substitution:'{F} / {q}',fields:[F('F','force','F','N',0.002,'signed'),F('q','probeCharge','q','C',1e-6,'nonzero')],result:'E',unit:'N/C'},
{id:'phys-plate-field',group:'fields',title:T('Field between parallel plates','Feld zwischen parallelen Platten','Campo entre placas paralelas','Champ entre plaques parallèles'),note:T('In the uniform field between parallel plates, field strength is voltage divided by plate separation.','Im homogenen Feld zwischen parallelen Platten ist die Feldstärke Spannung geteilt durch den Plattenabstand.','En el campo uniforme entre placas paralelas, la intensidad es tensión dividida entre la separación.','Dans le champ uniforme entre plaques parallèles, le champ est tension divisée par l’écartement.'),formula:'E = U / d',substitution:'{U} / {d}',fields:[F('U','voltage','U','V',12,'signed'),F('d','plateGap','d','m',0.02,'positive')],result:'E',unit:'V/m'},
{id:'phys-coulomb',group:'fields',title:T('Coulomb force','Coulombkraft','Fuerza de Coulomb','Force de Coulomb'),note:T('The force between two point charges is k q₁ q₂ / r². k is the Coulomb constant. Like charges repel when the product is positive.','Die Kraft zwischen zwei Punktladungen ist k q₁ q₂ / r². k ist die Coulomb-Konstante. Gleichnamige Ladungen stoßen sich ab, wenn das Produkt positiv ist.','La fuerza entre dos cargas puntuales es k q₁ q₂ / r². k es la constante de Coulomb. Cargas del mismo signo se repelen si el producto es positivo.','La force entre deux charges ponctuelles est k q₁ q₂ / r². k est la constante de Coulomb. Des charges de même signe se repoussent lorsque le produit est positif.'),formula:'F = k q₁ q₂ / r²',substitution:'k × {q1} × {q2} / {r}²',fields:[F('q1','charge1','q₁','C',2e-6,'signed'),F('q2','charge2','q₂','C',3e-6,'signed'),F('r','separation','r','m',0.2,'positive')],result:'F',unit:'N',constants:T('k = 8.9875517923 × 10⁹ N·m²/C².','k = 8,9875517923 × 10⁹ N·m²/C².','k = 8,9875517923 × 10⁹ N·m²/C².','k = 8,9875517923 × 10⁹ N·m²/C².')},
{id:'phys-radial-field',group:'fields',title:T('Field of a point charge','Feld einer Punktladung','Campo de una carga puntual','Champ d’une charge ponctuelle'),note:T('The radial electric field of a point charge is k q / r².','Das radiale elektrische Feld einer Punktladung ist k q / r².','El campo eléctrico radial de una carga puntual es k q / r².','Le champ électrique radial d’une charge ponctuelle est k q / r².'),formula:'E = k q / r²',substitution:'k × {q} / {r}²',fields:[F('q','charge','q','C',2e-6,'signed'),F('r','separation','r','m',0.2,'positive')],result:'E',unit:'N/C',constants:T('k = 8.9875517923 × 10⁹ N·m²/C².','k = 8,9875517923 × 10⁹ N·m²/C².','k = 8,9875517923 × 10⁹ N·m²/C².','k = 8,9875517923 × 10⁹ N·m²/C².')},
{id:'phys-capacitor-charge',group:'fields',title:T('Charge on a capacitor','Ladung eines Kondensators','Carga de un condensador','Charge d’un condensateur'),note:T('The charge stored at voltage U is capacitance times voltage.','Die bei der Spannung U gespeicherte Ladung ist Kapazität mal Spannung.','La carga almacenada a la tensión U es capacidad por tensión.','La charge stockée à la tension U est capacité fois tension.'),formula:'Q = C U',substitution:'{C} × {U}',fields:[F('C','capacitance','C','F',100e-6,'positive'),F('U','voltage','U','V',12,'signed')],result:'Q',unit:'C'},
{id:'phys-capacitor-energy',group:'fields',title:T('Energy in a capacitor','Energie eines Kondensators','Energía de un condensador','Énergie d’un condensateur'),note:T('The energy stored in the electric field of a capacitor is one half of capacitance times voltage squared.','Die im elektrischen Feld eines Kondensators gespeicherte Energie ist die Hälfte aus Kapazität mal Spannung zum Quadrat.','La energía almacenada en el campo eléctrico de un condensador es la mitad de la capacidad por la tensión al cuadrado.','L’énergie stockée dans le champ électrique d’un condensateur est la moitié de la capacité fois la tension au carré.'),formula:'W = ½ C U²',substitution:'0.5 × {C} × {U}²',fields:[F('C','capacitance','C','F',100e-6,'positive'),F('U','voltage','U','V',12,'signed')],result:'W',unit:'J'},
{id:'phys-capacitance',group:'fields',title:T('Capacitance of a parallel-plate capacitor','Kapazität eines Plattenkondensators','Capacidad de un condensador de placas','Capacité d’un condensateur plan'),note:T('Capacitance is ε₀ εᵣ A / d. ε₀ is the vacuum permittivity and εᵣ is the relative permittivity of the material between the plates.','Die Kapazität ist ε₀ εᵣ A / d. ε₀ ist die elektrische Feldkonstante und εᵣ die relative Permittivität des Stoffes zwischen den Platten.','La capacidad es ε₀ εᵣ A / d. ε₀ es la permitividad del vacío y εᵣ la permitividad relativa del material entre las placas.','La capacité est ε₀ εᵣ A / d. ε₀ est la permittivité du vide et εᵣ la permittivité relative du matériau entre les plaques.'),formula:'C = ε₀ εᵣ A / d',substitution:'ε₀ × {er} × {A} / {d}',fields:[F('er','permittivity','εᵣ','',2,'positive'),F('A','area','A','m²',0.02,'positive'),F('d','plateGap','d','m',0.001,'positive')],result:'C',unit:'F',constants:T('ε₀ = 8.8541878128 × 10⁻¹² F/m.','ε₀ = 8,8541878128 × 10⁻¹² F/m.','ε₀ = 8,8541878128 × 10⁻¹² F/m.','ε₀ = 8,8541878128 × 10⁻¹² F/m.')},
{id:'phys-flux-density',group:'fields',title:T('Magnetic flux density from the force on a wire','Magnetische Flussdichte aus der Leiterkraft','Densidad de flujo a partir de la fuerza sobre un conductor','Densité de flux à partir de la force sur un fil'),note:T('For a wire perpendicular to the field, flux density is force divided by current times length.','Für einen Leiter senkrecht zum Feld ist die Flussdichte Kraft geteilt durch Stromstärke mal Länge.','Para un conductor perpendicular al campo, la densidad de flujo es fuerza dividida entre intensidad por longitud.','Pour un fil perpendiculaire au champ, la densité de flux est force divisée par courant fois longueur.'),formula:'B = F / (I ℓ)',substitution:'{F} / ({I} × {L})',fields:[F('F','force','F','N',0.3,'nonnegative'),F('I','current','I','A',2,'positive'),F('L','wireLength','ℓ','m',0.3,'positive')],result:'B',unit:'T'},
{id:'phys-photon',group:'particles',title:T('Photon energy','Photonenenergie','Energía de un fotón','Énergie d’un photon'),note:T('Photon energy is proportional to frequency. The proportionality constant is the Planck constant h.','Die Photonenenergie ist proportional zur Frequenz. Die Proportionalitätskonstante ist das Planck’sche Wirkungsquantum h.','La energía del fotón es proporcional a la frecuencia. La constante de proporcionalidad es la constante de Planck h.','L’énergie du photon est proportionnelle à la fréquence. La constante de proportionnalité est la constante de Planck h.'),formula:'E = h f',substitution:'h × {f}',fields:[F('f','frequency','f','Hz',5e14,'positive')],result:'E',unit:'J',constants:T('h = 6.62607015 × 10⁻³⁴ J·s.','h = 6,62607015 × 10⁻³⁴ J·s.','h = 6,62607015 × 10⁻³⁴ J·s.','h = 6,62607015 × 10⁻³⁴ J·s.')},
{id:'phys-well',group:'particles',title:T('Infinite square-well energy','Energie im unendlich tiefen Potentialtopf','Energía del pozo cuadrado infinito','Énergie du puits carré infini'),note:T('In a one-dimensional infinite well the level n, starting at 1, has energy n² h² / (8 m L²). n = 0 is not a level. The sample uses an electron in a well 1 nm wide.','In einem eindimensionalen unendlich tiefen Potentialtopf hat das Niveau n, beginnend bei 1, die Energie n² h² / (8 m L²). n = 0 ist kein Niveau. Das Beispiel ist ein Elektron in einem 1 nm breiten Topf.','En un pozo infinito unidimensional, el nivel n, desde 1, tiene energía n² h² / (8 m L²). n = 0 no es un nivel. El ejemplo es un electrón en un pozo de 1 nm de anchura.','Dans un puits infini à une dimension, le niveau n, à partir de 1, a l’énergie n² h² / (8 m L²). n = 0 n’est pas un niveau. L’exemple est un électron dans un puits de 1 nm de large.'),formula:'Eₙ = n² h² / (8 m L²)',substitution:'{n}² × h² / (8 × {m} × {L}²)',fields:[F('n','level','n','',1,'integer'),F('m','mass','m','kg',9.1093837e-31,'positive'),F('L','wellWidth','L','m',1e-9,'positive')],result:'Eₙ',unit:'J',constants:T('h = 6.62607015 × 10⁻³⁴ J·s.','h = 6,62607015 × 10⁻³⁴ J·s.','h = 6,62607015 × 10⁻³⁴ J·s.','h = 6,62607015 × 10⁻³⁴ J·s.')},
{id:'phys-photon-momentum',group:'particles',title:T('Photon momentum','Photonenimpuls','Momento de un fotón','Quantité de mouvement d’un photon'),note:T('The momentum of a photon is the Planck constant divided by the wavelength.','Der Impuls eines Photons ist das Planck’sche Wirkungsquantum geteilt durch die Wellenlänge.','El momento de un fotón es la constante de Planck dividida entre la longitud de onda.','La quantité de mouvement d’un photon est la constante de Planck divisée par la longueur d’onde.'),formula:'p = h / λ',substitution:'h / {lambda}',fields:[F('lambda','wavelength','λ','m',5e-7,'positive')],result:'p',unit:'kg·m/s',constants:T('h = 6.62607015 × 10⁻³⁴ J·s.','h = 6,62607015 × 10⁻³⁴ J·s.','h = 6,62607015 × 10⁻³⁴ J·s.','h = 6,62607015 × 10⁻³⁴ J·s.')},
{id:'phys-debroglie',group:'particles',title:T('de Broglie wavelength','De-Broglie-Wellenlänge','Longitud de onda de de Broglie','Longueur d’onde de de Broglie'),note:T('For an electron, wavelength and momentum are linked by λ = h/p. h is the same Planck constant.','Für ein Elektron hängen Wellenlänge und Impuls über λ = h/p zusammen. h ist dasselbe Planck’sche Wirkungsquantum.','Para un electrón, la longitud de onda y el momento se relacionan por λ = h/p. h es la misma constante de Planck.','Pour un électron, longueur d’onde et quantité de mouvement sont liées par λ = h/p. h est la même constante de Planck.'),formula:'λ = h / p',substitution:'h / {p}',fields:[F('p','momentum','p','kg·m/s',1e-24,'positive')],result:'λ',unit:'m',constants:T('h = 6.62607015 × 10⁻³⁴ J·s.','h = 6,62607015 × 10⁻³⁴ J·s.','h = 6,62607015 × 10⁻³⁴ J·s.','h = 6,62607015 × 10⁻³⁴ J·s.')},
{id:'phys-mass-energy',group:'particles',title:T('Energy from a mass difference','Energie aus einer Massendifferenz','Energía a partir de una diferencia de masa','Énergie à partir d’une différence de masse'),note:T('A mass difference Δm corresponds to the energy Δm c². c is the speed of light in vacuum.','Einer Massendifferenz Δm entspricht die Energie Δm c². c ist die Lichtgeschwindigkeit im Vakuum.','Una diferencia de masa Δm corresponde a la energía Δm c². c es la velocidad de la luz en el vacío.','Une différence de masse Δm correspond à l’énergie Δm c². c est la vitesse de la lumière dans le vide.'),formula:'E = Δm c²',substitution:'{dm} × c²',fields:[F('dm','massDefect','Δm','kg',1.6605390666e-27,'signed')],result:'E',unit:'J',constants:T('c = 299792458 m/s.','c = 299792458 m/s.','c = 299792458 m/s.','c = 299792458 m/s.')},
{id:'phys-binding',group:'particles',title:T('Binding energy per nucleon','Bindungsenergie je Nukleon','Energía de enlace por nucleón','Énergie de liaison par nucléon'),note:T('Divide the total binding energy by the number of nucleons.','Teile die gesamte Bindungsenergie durch die Nukleonenzahl.','Divide la energía de enlace total entre el número de nucleones.','Divise l’énergie de liaison totale par le nombre de nucléons.'),formula:'ε = E / A',substitution:'{E} / {A}',fields:[F('E','energy','E','J',1.5e-10,'nonnegative'),F('A','nucleons','A','',56,'integer')],result:'ε',unit:'J'},
{id:'phys-decay',group:'particles',title:T('Radioactive decay','Radioaktiver Zerfall','Desintegración radiactiva','Désintégration radioactive'),note:T('After time t the remaining number is the initial number times one half raised to t divided by the half-life.','Nach der Zeit t ist die verbleibende Anzahl die Anfangszahl mal ein Halb hoch t geteilt durch die Halbwertszeit.','Tras el tiempo t, el número restante es el inicial por un medio elevado a t dividido entre el periodo de semidesintegración.','Après la durée t, le nombre restant est le nombre initial fois un demi élevé à t divisé par la demie-vie.'),formula:'N = N₀ (1/2)^(t / T)',substitution:'{N0} × (1/2) ^ ({t} / {T})',fields:[F('N0','initialCount','N₀','',800,'nonnegative'),F('t','duration','t','s',10,'nonnegative'),F('T','halfLife','T','s',5,'positive')],result:'N',unit:''},
{id:'phys-activity',group:'particles',title:T('Activity','Aktivität','Actividad','Activité'),note:T('Activity is the decay constant times the number of nuclei. The decay constant is ln 2 divided by the half-life.','Die Aktivität ist die Zerfallskonstante mal die Kernzahl. Die Zerfallskonstante ist ln 2 geteilt durch die Halbwertszeit.','La actividad es la constante de desintegración por el número de núcleos. La constante es ln 2 dividido entre el periodo de semidesintegración.','L’activité est la constante de désintégration fois le nombre de noyaux. La constante est ln 2 divisé par la demie-vie.'),formula:'A = (ln 2) N / T',substitution:'ln(2) × {N} / {T}',fields:[F('N','nuclei','N','',800,'nonnegative'),F('T','halfLife','T','s',5,'positive')],result:'A',unit:'1/s'},
{id:'phys-dose',group:'particles',title:T('Absorbed dose','Energiedosis','Dosis absorbida','Dose absorbée'),note:T('Absorbed dose is the energy deposited divided by the mass that absorbs it.','Die Energiedosis ist die deponierte Energie geteilt durch die Masse, die sie aufnimmt.','La dosis absorbida es la energía depositada dividida entre la masa que la absorbe.','La dose absorbée est l’énergie déposée divisée par la masse qui l’absorbe.'),formula:'D = E / m',substitution:'{E} / {m}',fields:[F('E','energy','E','J',0.01,'nonnegative'),F('m','mass','m','kg',0.05,'positive')],result:'D',unit:'Gy'},
{id:'phys-equivalent',group:'particles',title:T('Equivalent dose','Äquivalentdosis','Dosis equivalente','Dose équivalente'),note:T('Equivalent dose is the radiation weighting factor times the absorbed dose.','Die Äquivalentdosis ist der Strahlungs-Wichtungsfaktor mal die Energiedosis.','La dosis equivalente es el factor de ponderación de la radiación por la dosis absorbida.','La dose équivalente est le facteur de pondération radiologique fois la dose absorbée.'),formula:'H = w D',substitution:'{w} × {D}',fields:[F('w','weighting','w','',1,'positive'),F('D','energy','D','Gy',0.2,'nonnegative')],result:'H',unit:'Sv'},
{id:'phys-gamma',group:'particles',title:T('Lorentz factor','Lorentz-Faktor','Factor de Lorentz','Facteur de Lorentz'),note:T('For a speed v slower than light, γ = 1/√(1 − v²/c²). c is the speed of light in vacuum.','Für eine Geschwindigkeit v kleiner als die Lichtgeschwindigkeit gilt γ = 1/√(1 − v²/c²). c ist die Lichtgeschwindigkeit im Vakuum.','Para una rapidez v menor que la de la luz, γ = 1/√(1 − v²/c²). c es la velocidad de la luz en el vacío.','Pour une vitesse v inférieure à celle de la lumière, γ = 1/√(1 − v²/c²). c est la vitesse de la lumière dans le vide.'),formula:'γ = 1 / √(1 − v²/c²)',substitution:'1 / √(1 − {v}² / c²)',fields:[F('v','speed','v','m/s',0.6*299792458,'nonnegative')],result:'γ',unit:'',constants:T('c = 299792458 m/s.','c = 299792458 m/s.','c = 299792458 m/s.','c = 299792458 m/s.')},
{id:'phys-dilation',group:'particles',title:T('Time dilation','Zeitdilatation','Dilatación del tiempo','Dilatation du temps'),note:T('A clock moving at speed v records a shorter proper time. The longer coordinate time is γ times that proper time.','Eine mit der Geschwindigkeit v bewegte Uhr zeigt eine kürzere Eigenzeit. Die längere Koordinatenzeit ist γ mal diese Eigenzeit.','Un reloj que se mueve a rapidez v marca un tiempo propio más corto. El tiempo coordenado más largo es γ por ese tiempo propio.','Une horloge qui se déplace à la vitesse v indique un temps propre plus court. Le temps coordonné plus long est γ fois ce temps propre.'),formula:'Δt = γ Δτ',substitution:'{tau} / √(1 − {v}² / c²)',fields:[F('v','speed','v','m/s',0.6*299792458,'nonnegative'),F('tau','properTime','Δτ','s',1,'nonnegative')],result:'Δt',unit:'s',constants:T('c = 299792458 m/s.','c = 299792458 m/s.','c = 299792458 m/s.','c = 299792458 m/s.')},
{id:'phys-contraction',group:'particles',title:T('Length contraction','Längenkontraktion','Contracción de la longitud','Contraction des longueurs'),note:T('A length moving lengthwise at speed v is shorter than its proper length by the factor 1/γ.','Eine in Bewegungsrichtung mit der Geschwindigkeit v bewegte Länge ist um den Faktor 1/γ kürzer als ihre Eigenlänge.','Una longitud que se mueve en su propia dirección a rapidez v es más corta que su longitud propia por el factor 1/γ.','Une longueur qui se déplace dans sa direction à la vitesse v est plus courte que sa longueur propre par le facteur 1/γ.'),formula:'L = L₀ / γ',substitution:'{L0} × √(1 − {v}² / c²)',fields:[F('v','speed','v','m/s',0.6*299792458,'nonnegative'),F('L0','properLength','L₀','m',1,'nonnegative')],result:'L',unit:'m',constants:T('c = 299792458 m/s.','c = 299792458 m/s.','c = 299792458 m/s.','c = 299792458 m/s.')},
{id:'phys-rel-energy',group:'particles',title:T('Relativistic energy','Relativistische Energie','Energía relativista','Énergie relativiste'),note:T('The total energy of a body of rest mass m moving at speed v is γ m c².','Die Gesamtenergie eines Körpers der Ruhemasse m mit der Geschwindigkeit v ist γ m c².','La energía total de un cuerpo de masa en reposo m que se mueve a rapidez v es γ m c².','L’énergie totale d’un corps de masse au repos m se déplaçant à la vitesse v est γ m c².'),formula:'E = γ m c²',substitution:'{m} × c² / √(1 − {v}² / c²)',fields:[F('m','restMass','m','kg',9.1093837e-31,'positive'),F('v','speed','v','m/s',0.6*299792458,'nonnegative')],result:'E',unit:'J',constants:T('c = 299792458 m/s.','c = 299792458 m/s.','c = 299792458 m/s.','c = 299792458 m/s.')},
{id:'phys-energy-momentum',group:'particles',title:T('Energy–momentum relation','Energie-Impuls-Beziehung','Relación energía–momento','Relation énergie–quantité de mouvement'),note:T('Total energy, momentum and rest mass are linked by E = √((pc)² + (mc²)²).','Gesamtenergie, Impuls und Ruhemasse hängen über E = √((pc)² + (mc²)²) zusammen.','La energía total, el momento y la masa en reposo se relacionan por E = √((pc)² + (mc²)²).','L’énergie totale, la quantité de mouvement et la masse au repos sont liées par E = √((pc)² + (mc²)²).'),formula:'E = √((p c)² + (m c²)²)',substitution:'√(({p} × c)² + ({m} × c²)²)',fields:[F('p','momentum','p','kg·m/s',1e-22,'nonnegative'),F('m','restMass','m','kg',9.1093837e-31,'nonnegative')],result:'E',unit:'J',constants:T('c = 299792458 m/s.','c = 299792458 m/s.','c = 299792458 m/s.','c = 299792458 m/s.')}
];
const nCards=physicsCards.length;
physicsUI.intro=T(
 `Explore ${nCards} interactive calculations, organised by topic. Start with the sample values, then change one quantity at a time.`,
 `Entdecke ${nCards} interaktive Berechnungen nach Themen. Starte mit den Beispielwerten und ändere jeweils eine Größe.`,
 `Explora ${nCards} cálculos interactivos organizados por temas. Empieza con los valores de ejemplo y cambia una magnitud cada vez.`,
 `Explore ${nCards} calculs interactifs classés par thème. Commence avec les valeurs d’exemple, puis modifie une grandeur à la fois.`
);
export const physText=key=>physicsUI[key][getLanguage()];
export const groupText=key=>groupNames[key][getLanguage()];
export const labelText=key=>fieldLabels[key][getLanguage()];
const {g,e,h,c,mu0,eps0,k,sigma,wien,G,R}=constants;
const rad=degrees=>degrees*Math.PI/180;
const deg=radians=>radians*180/Math.PI;
const gamma=v=>1/Math.sqrt(1-(v*v)/(c*c));
const calculations={
'phys-speed':v=>v.s/v.t,
'phys-acceleration':v=>v.dv/v.t,
'phys-uniform':v=>v.v*v.t,
'phys-accel-speed':v=>v.v0+v.a*v.t,
'phys-accel-distance':v=>v.v0*v.t+0.5*v.a*v.t*v.t,
'phys-accel-link':v=>Math.sqrt(v.v0*v.v0+2*v.a*v.s),
'phys-throw-horizontal':v=>v.v*v.t,
'phys-throw-vertical':v=>0.5*v.g*v.t*v.t,
'phys-newton':v=>v.m*v.a,
'phys-impulse':v=>v.m*v.dv/v.t,
'phys-weight':v=>v.m*v.g,
'phys-centripetal':v=>v.m*v.v*v.v/v.r,
'phys-gravity':v=>G*v.m1*v.m2/(v.r*v.r),
'phys-kepler-period':v=>v.T1*(v.a2/v.a1)**1.5,
'phys-kepler-axis':v=>v.a1*Math.cbrt((v.T2/v.T1)**2),
'phys-hooke':v=>v.D*v.x,
'phys-hydrostatic':v=>v.rho*v.g*v.h,
'phys-buoyancy':v=>v.rho*v.V*v.g,
'phys-kinetic':v=>0.5*v.m*v.v*v.v,
'phys-height':v=>v.m*v.g*v.h,
'phys-work':v=>v.F*v.s,
'phys-power':v=>v.W/v.t,
'phys-drop-speed':v=>Math.sqrt(2*v.g*v.h),
'phys-momentum':v=>v.m*v.v,
'phys-collision':v=>(v.m1*v.u1+v.m2*v.u2)/(v.m1+v.m2),
'phys-pendulum':v=>v.T1*Math.sqrt(v.l2/v.l1),
'phys-ohm':v=>v.U/v.I,
'phys-ohm-current':v=>v.U/v.R,
'phys-current-charge':v=>v.Q/v.t,
'phys-elementary':v=>v.N*e,
'phys-electric-power':v=>v.U*v.I,
'phys-electric-energy':v=>v.U*v.I*v.t,
'phys-efficiency':v=>v.useful/v.supplied,
'phys-series':v=>v.R1+v.R2+v.R3,
'phys-parallel':v=>1/(1/v.R1+1/v.R2),
'phys-reflection':v=>v.theta,
'phys-snell-angle2':v=>deg(Math.asin(v.n1*Math.sin(rad(v.theta1))/v.n2)),
'phys-snell-angle1':v=>deg(Math.asin(v.n2*Math.sin(rad(v.theta2))/v.n1)),
'phys-snell-n2':v=>v.n1*Math.sin(rad(v.theta1))/Math.sin(rad(v.theta2)),
'phys-snell-n1':v=>v.n2*Math.sin(rad(v.theta2))/Math.sin(rad(v.theta1)),
'phys-lens-image':v=>v.u*v.f/(v.u-v.f),
'phys-lens-object':v=>v.v*v.f/(v.v-v.f),
'phys-lens-focal':v=>v.u*v.v/(v.u+v.v),
'phys-fringe':v=>v.lambda*v.L/v.d,
'phys-path':v=>v.n*v.lambda,
'phys-bragg':v=>2*v.d*Math.sin(v.theta*Math.PI/180)/v.n,
'phys-heat':v=>v.c*v.m*v.dT,
'phys-gas-pressure':v=>v.n*R*v.T/v.V,
'phys-gas-volume':v=>v.n*R*v.T/v.P,
'phys-gas-amount':v=>v.P*v.V/(R*v.T),
'phys-gas-temperature':v=>v.P*v.V/(v.n*R),
'phys-conduction':v=>v.lambda*v.A*v.dT/v.d,
'phys-wien':v=>wien/v.T,
'phys-stefan':v=>sigma*v.A*v.T**4,
'phys-flux':v=>v.B*v.A,
'phys-induction':v=>v.N*Math.abs(v.dPhi)/v.t,
'phys-lorentz-charge':v=>v.q*v.v*v.B,
'phys-lorentz-wire':v=>v.I*v.L*v.B,
'phys-cyclotron':v=>v.m*v.v/(v.q*v.B),
'phys-inductor':v=>v.L*Math.abs(v.dI)/v.t,
'phys-coil-energy':v=>0.5*v.L*v.I*v.I,
'phys-coil-field':v=>mu0*v.N*v.I/v.L,
'phys-transformer-voltage':v=>v.U1*v.N2/v.N1,
'phys-transformer-current':v=>v.I1*v.N1/v.N2,
'phys-wave':v=>v.f*v.lambda,
'phys-thomson':v=>2*Math.PI*Math.sqrt(v.L*v.C),
'phys-rc':v=>v.R*v.C,
'phys-spring-period':v=>2*Math.PI*Math.sqrt(v.m/v.D),
'phys-field':v=>v.F/v.q,
'phys-plate-field':v=>v.U/v.d,
'phys-coulomb':v=>k*v.q1*v.q2/(v.r*v.r),
'phys-radial-field':v=>k*v.q/(v.r*v.r),
'phys-capacitor-charge':v=>v.C*v.U,
'phys-capacitor-energy':v=>0.5*v.C*v.U*v.U,
'phys-capacitance':v=>eps0*v.er*v.A/v.d,
'phys-flux-density':v=>v.F/(v.I*v.L),
'phys-photon':v=>h*v.f,
'phys-well':v=>v.n*v.n*h*h/(8*v.m*v.L*v.L),
'phys-photon-momentum':v=>h/v.lambda,
'phys-debroglie':v=>h/v.p,
'phys-mass-energy':v=>v.dm*c*c,
'phys-binding':v=>v.E/v.A,
'phys-decay':v=>v.N0*0.5**(v.t/v.T),
'phys-activity':v=>Math.LN2*v.N/v.T,
'phys-dose':v=>v.E/v.m,
'phys-equivalent':v=>v.w*v.D,
'phys-gamma':v=>gamma(v.v),
'phys-dilation':v=>v.tau*gamma(v.v),
'phys-contraction':v=>v.L0/gamma(v.v),
'phys-rel-energy':v=>v.m*c*c*gamma(v.v),
'phys-energy-momentum':v=>Math.hypot(v.p*c,v.m*c*c)
};
const validations={
'phys-accel-link':v=>v.v0*v.v0+2*v.a*v.s<0?'realSpeed':null,
'phys-efficiency':v=>v.useful>v.supplied?'fraction':null,
'phys-reflection':v=>v.theta>90?'mirror':null,
'phys-snell-angle2':v=>v.theta1>=90?'optic':Math.abs(v.n1*Math.sin(rad(v.theta1)))>v.n2?'snell':null,
'phys-snell-angle1':v=>v.theta2>=90?'optic':Math.abs(v.n2*Math.sin(rad(v.theta2)))>v.n1?'snell':null,
'phys-snell-n2':v=>v.theta1>=90||v.theta2>=90?'optic':null,
'phys-snell-n1':v=>v.theta1>=90||v.theta2>=90?'optic':null,
'phys-lens-image':v=>v.u===v.f?'lens':null,
'phys-lens-object':v=>v.v===v.f?'lens':null,
'phys-lens-focal':v=>v.u+v.v===0?'lens':null,
'phys-bragg':v=>v.theta>=90?'bragg':null,
'phys-gamma':v=>v.v>=c?'light':null,
'phys-dilation':v=>v.v>=c?'light':null,
'phys-contraction':v=>v.v>=c?'light':null,
'phys-rel-energy':v=>v.v>=c?'light':null
};
for(const card of physicsCards){card.calculate=calculations[card.id];card.validate=validations[card.id];if(card.constants&&typeof card.constants==='object'){card.constantText=card.constants;card.constants=card.constantText.en;}}
